  CREATE FUNCTION public.fn_izo_gps_curata(p_limita int DEFAULT 5000) RETURNS int
   LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 DECLARE v_r record; v_n int:=0; v_deleted int; v_run uuid:=gen_random_uuid();
  v_old_ctx text:=current_setting('izo.gps_curata_ctx',true);
